import string, itertools

ct = "esnp{d0c_@yz@gl_mn0j_pm3z3_g0_o00s}"
inner = ct[5:-1]

print("=== Caesar (letters only, preserve case) ===")
for k in range(26):
    out = ''.join(chr((ord(c)-65+k)%26+65) if c.isupper() else (chr((ord(c)-97+k)%26+97) if c.islower() else c) for c in ct)
    print(k, out)

print("=== ROT47 ===")
print(''.join(chr((ord(c)-33+47)%94+33) if 33 <= ord(c) <= 126 else c for c in ct))

print("=== Atbash ===")
print(''.join(chr(219-ord(c)) if c.islower() else (chr(155-ord(c)) if c.isupper() else c) for c in ct))

print("=== Keyboard shift left/right ===")
rows = ["qwertyuiop", "asdfghjkl", "zxcvbnm"]
def shift(s, d):
    out=[]
    for c in s:
        lc=c.lower()
        done=False
        for r in rows:
            if lc in r:
                i=r.index(lc)
                j=i+d
                if 0<=j<len(r):
                    nc=r[j]
                    out.append(nc.upper() if c.isupper() else nc)
                else:
                    out.append(c)
                done=True
                break
        if not done: out.append(c)
    return ''.join(out)
print("left :", shift(ct,-1))
print("right:", shift(ct,1))

print("=== Keyboard row up/down ===")
def vshift(s, d):
    # rows offsets roughly
    rowmap = {}
    for ri,r in enumerate(rows):
        for ci,c in enumerate(r):
            rowmap[c]=(ri,ci)
    out=[]
    for c in s:
        lc=c.lower()
        if lc in rowmap:
            ri,ci=rowmap[lc]
            nr=ri+d
            if 0<=nr<len(rows):
                r=rows[nr]
                ci2=min(ci,len(r)-1)
                nc=r[ci2]
                out.append(nc.upper() if c.isupper() else nc)
            else:
                out.append(c)
        else:
            out.append(c)
    return ''.join(out)
print("up  :", vshift(ct,-1))
print("down:", vshift(ct,1))

print("=== QWERTY<->Dvorak ===")
q = "qwertyuiop[]asdfghjkl;'zxcvbnm,./"
d = "',.pyfgcrl/=aoeuidhtns-;qjkxbmwvz"
print("q->d:", ct.translate(str.maketrans(q,d)))
print("d->q:", ct.translate(str.maketrans(d,q)))

